import React from 'react';
import { Document, Packer, Paragraph, TextRun } from 'docx';
import { saveAs } from 'file-saver';

function DownloadDOCX({ resumeData }) {
  const handleDownload = async () => {
    const doc = new Document({
      sections: [
        {
          properties: {},
          children: [
            new Paragraph({
              children: [
                new TextRun({ text: resumeData.name || '', bold: true, size: 32 }),
              ],
              alignment: 'center',
            }),
            new Paragraph({
              children: [
                new TextRun({ text: `Email: ${resumeData.email || ''}    Phone: ${resumeData.phone || ''}`, size: 24 }),
              ],
              alignment: 'center',
            }),
            new Paragraph({ text: '' }),
            new Paragraph({ text: 'Professional Summary', bold: true, size: 28 }),
            new Paragraph({ text: resumeData.summary || '' }),
            new Paragraph({ text: '' }),
            new Paragraph({ text: 'Experience', bold: true, size: 28 }),
            new Paragraph({ text: resumeData.experience || '' }),
            new Paragraph({ text: '' }),
            new Paragraph({ text: 'Education', bold: true, size: 28 }),
            new Paragraph({ text: resumeData.education || '' }),
            new Paragraph({ text: '' }),
            new Paragraph({ text: 'Skills', bold: true, size: 28 }),
            ...(Array.isArray(resumeData.skills)
              ? resumeData.skills.map(skill => new Paragraph({ text: `• ${skill}` }))
              : (resumeData.skills || '').split(',').map(skill => new Paragraph({ text: `• ${skill.trim()}` }))),
          ],
        },
      ],
    });
    const blob = await Packer.toBlob(doc);
    saveAs(blob, 'resume.docx');
  };

  return (
    <button onClick={handleDownload} style={{marginTop: '16px', marginLeft: '8px', padding: '10px 20px', background: '#2563eb', color: '#fff', border: 'none', borderRadius: '4px', cursor: 'pointer'}}>
      Download as DOCX
    </button>
  );
}

export default DownloadDOCX;
